import os
import io
import json
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _coord_value(point: Dict[str, Any], key: str) -> float:
    value = point.get(key)
    if value is None:
        return 0.0
    return float(value)


def _bbox_from_geometry(geometry: Dict[str, Any]) -> Dict[str, float]:
    polygon = geometry.get("Polygon") or geometry.get("polygon") or []
    if not polygon:
        return {"left": 0.0, "top": 0.0, "width": 0.0, "height": 0.0}
    xs = [_coord_value(p, "X") for p in polygon]
    ys = [_coord_value(p, "Y") for p in polygon]
    left = min(xs)
    top = min(ys)
    right = max(xs)
    bottom = max(ys)
    return {"left": left, "top": top, "width": right - left, "height": bottom - top}


def _cell_text_from_relationships(block_map: Dict[str, Dict[str, Any]], cell: Dict[str, Any]) -> str:
    texts: List[str] = []
    for rel in cell.get("Relationships", []):
        if rel.get("Type") == "CHILD":
            for child_id in rel.get("Ids", []):
                child = block_map.get(child_id)
                if not child:
                    continue
                if child.get("BlockType") == "WORD":
                    texts.append(child.get("Text", ""))
                elif child.get("BlockType") == "SELECTION_ELEMENT":
                    if child.get("SelectionStatus") == "SELECTED":
                        texts.append("X")
    return " ".join(t for t in texts if t).strip()


def extract_table_cells_and_rows(
    document_path: Optional[str] = None,
    document_bytes: Optional[bytes] = None,
    aws_region: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract table cells and row structure from a document using Amazon Textract.

    Returns a dict with:
      - tables: list of tables, each with cells and rows
      - raw_blocks: all Textract blocks
    """
    if document_path is None and document_bytes is None:
        raise ValueError("Provide either document_path or document_bytes.")

    region = aws_region or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    textract = boto3.client("textract", region_name=region)

    if document_path is not None:
        with open(document_path, "rb") as f:
            document_bytes = f.read()

    assert document_bytes is not None

    try:
        response = textract.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["TABLES"],
        )
    except (BotoCoreError, ClientError):
        response = textract.detect_document_text(
            Document={"Bytes": document_bytes},
        )

    blocks = response.get("Blocks", [])
    block_map = {b["Id"]: b for b in blocks if "Id" in b}

    tables_out: List[Dict[str, Any]] = []

    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        table: Dict[str, Any] = {
            "geometry": _bbox_from_geometry(block.get("Geometry", {})),
            "cells": [],
            "rows": [],
        }

        cell_blocks: List[Dict[str, Any]] = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") == "CHILD":
                for child_id in rel.get("Ids", []):
                    child = block_map.get(child_id)
                    if child and child.get("BlockType") == "CELL":
                        cell_blocks.append(child)

        cell_items: List[Dict[str, Any]] = []
        for cell in cell_blocks:
            row_index = int(cell.get("RowIndex", 0))
            col_index = int(cell.get("ColumnIndex", 0))
            row_span = int(cell.get("RowSpan", 1))
            col_span = int(cell.get("ColumnSpan", 1))
            item = {
                "row_index": row_index,
                "column_index": col_index,
                "row_span": row_span,
                "column_span": col_span,
                "text": _cell_text_from_relationships(block_map, cell),
                "bbox": _bbox_from_geometry(cell.get("Geometry", {})),
            }
            cell_items.append(item)

        table["cells"] = sorted(cell_items, key=lambda c: (c["row_index"], c["column_index"]))

        rows: Dict[int, List[Dict[str, Any]]] = {}
        for cell in table["cells"]:
            rows.setdefault(cell["row_index"], []).append(cell)

        for row_idx in sorted(rows.keys()):
            row_cells = sorted(rows[row_idx], key=lambda c: c["column_index"])
            table["rows"].append(
                {
                    "row_index": row_idx,
                    "cells": row_cells,
                    "texts": [c["text"] for c in row_cells],
                }
            )

        tables_out.append(table)

    return {"tables": tables_out, "raw_blocks": blocks}


def extract_table_cells_and_rows_from_file(document_path: str, aws_region: Optional[str] = None) -> Dict[str, Any]:
    return extract_table_cells_and_rows(document_path=document_path, aws_region=aws_region)


def extract_table_cells_and_rows_from_bytes(document_bytes: bytes, aws_region: Optional[str] = None) -> Dict[str, Any]:
    return extract_table_cells_and_rows(document_bytes=document_bytes, aws_region=aws_region)
